  if (lk === 'senior') return `<section class="hero"><div class="wrap hc">${d.eyebrow ? `<p class="pill">${esc(d.eyebrow)}</p>` : ''}<h1>${h1}</h1><p class="hs">${esc(d.sub || '')}</p>${btns}<svg class="ill" viewBox="0 0 360 150" aria-hidden="true"><ellipse cx="180" cy="140" rx="170" ry="10" fill="${rgba(s.color, .12)}"/><rect x="40" y="40" width="70" height="96" rx="12" fill="#fff" stroke="${s.color}" stroke-width="3"/><rect x="50" y="52" width="50" height="62" rx="6" fill="${rgba(s.color, .15)}"/><circle cx="75" cy="124" r="4" fill="${s.color}"/><circle cx="190" cy="62" r="26" fill="#FFE2C6"/><path d="M152 136c0-28 17-46 38-46s38 18 38 46z" fill="${s.color}"/><circle cx="276" cy="66" r="24" fill="#FFE2C6"/><path d="M240 136c0-26 16-42 36-42s36 16 36 42z" fill="#F6B04A"/><path d="M300 30l6 12 13 2-9 9 2 13-12-6-12 6 2-13-9-9 13-2z" fill="#F6C94A"/></svg></div></section>`;
  if (lk === 'brandBold') {     return `<section class="hero"><div class="wrap hg"><div>${ey}<h1>${h1}</h1><p class="hs">${esc(d.sub || '')}</p>${btns}</div><div class="rpt" aria-hidden="true"><div class="rh"><b>이번 주 학습 리포트</b><span>${esc(spOrg())}</span></div>${[['출석', 100], ['과제 제출', 92], ['테스트 성취', 86], ['클리닉 참여', 78]].map(([a, v]) => `<div class="rr"><small>${a}</small><i><em style="width:${v}%"></em></i><b>${v}%</b></div>`).join('')}<div class="rf">✓ 보호자 알림 발송 완료</div></div></div></section>${stats ? `<div class="strip"><div class="wrap"><span class="badge">${esc(spOrg())}</span><b class="q">“${esc((d.sub || '').split(/[.·]/)[0])}”</b><div class="sts">${(d.stats || []).map(([a, b]) => `<span><b>${esc(a)}</b><small>${esc(b)}</small></span>`).join('')}</div></div></div>` : ''}`; }
  if (lk === 'corpPortal') return `<section class="hero"><i class="beam b1"></i><i class="beam b2"></i><div class="wrap">${ey}<h1>${h1}</h1><p class="hs">${esc(d.sub || '')}</p>${btns}${(d.chips || []).length ? `<div class="fbox">${d.chips.map(([n, a, b]) => `<div><small>${esc(n)}</small><b>${esc(a)}</b><p>${esc(b || '')}</p></div>`).join('')}</div>` : ''}</div></section>`;
  if (lk === 'storyNumbered') return `<section class="hero"><i class="cl c1"></i><i class="cl c2"></i><div class="wrap hg"><div>${ey}<h1>${h1}</h1><i class="ln"></i><p class="hs">${esc(d.sub || '')}</p>${btns}</div><div class="pass" aria-hidden="true"><div class="ph1"><b>Learning Pass</b><small>${esc(spOrg())}</small></div><div class="ph2"><div><small>FROM</small><b>START</b></div><span>✈</span><div><small>TO</small><b>EXPERT</b></div></div><div class="ph3"><div><small>Course</small><b>${esc((S.classes[0]?.name || '대표 과정').slice(0, 14))}</b></div><i class="qr"></i></div></div></div></section>`;
