siteHTML = (s, full, lang) => {
  lang = lang || UI.pvLang || 'ko'; const lk = lookOf(s); const ft = S.settings.footer;
  const s2 = lang !== 'ko' ? { ...s, sections: s.tr?.[lang] || s.sections } : s;
  const menus = s.menus.filter(m => m.on).map(m => `<a href="#">${esc(lang !== 'ko' ? LX(m.l, lang) : m.l)}${m.access !== '공개' ? ` <i>(${esc(m.access)})</i>` : ''}</a>`).join('');
  const lsw = (s.langs || []).length > 1 ? `<span class="lsw">${s.langs.map(l => `<a href="#" class="${l === lang ? 'on' : ''}">${esc(langName(l))}</a>`).join(' · ')}</span>` : '';
  const band = lang !== 'ko' && !s.tr?.[lang] ? `<div style="background:#FFF3D6;color:#8A5A00;padding:8px 16px;font-size:13px">${esc(langName(lang))} 본문은 아직 생성되지 않았습니다 — 메뉴만 언어팩으로 표시 중</div>` : '';
  const body = s2.sections.map((x, i) => proSec(x, i, s, lk)).join('');
  return `<!doctype html><html lang="${lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(S.settings.seo?.title || S.org.name)}</title>${full ? `<meta name="description" content="${esc(S.settings.seo?.desc || '')}"><link rel="stylesheet" href="https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/variable/pretendardvariable.min.css">` : ''}<meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src https://i.ytimg.com data:; style-src 'unsafe-inline' https://cdn.jsdelivr.net; font-src https://cdn.jsdelivr.net"><style>${proCSS(s, lk)}</style></head><body class="lk-${lk}">${band}
<header class="gh"><div class="wrap"><a class="logo" href="#"><i>${esc(spOrg().slice(0, 1))}</i>${esc(S.org.name)}</a><nav class="gn">${menus}</nav><div class="hr">${lsw}<a class="j" href="#">${esc(LX('가입하기', lang) || '가입하기')}</a><a class="l" href="#">${esc(LX('로그인', lang))}</a></div></div></header>
${body}
<footer class="gf"><div class="wrap"><div><b>${esc(S.org.name)}</b><p>${esc(ft.company || S.org.name)} · 대표 ${esc(ft.ceo || '—')} · 사업자등록번호 ${esc(ft.biz || '—')} · 통신판매업 ${esc(ft.mail || '—')}</p><p>${esc(ft.addr || '주소 미입력')} · ${esc(ft.tel || '연락처 미입력')}</p><p>©Copyright ${esc(S.org.name)} All rights reserved · Powered by 디디쌤</p></div><div class="fl2"><span>서비스 이용약관</span><span>개인정보 처리방침</span><span>학습자 가이드</span></div></div></footer></body></html>`;
};

