{ const base = ACT['site-edit']; ACT['site-edit'] = el => { const i = +el.dataset.v, x = site().sections[i], d = x.data; if (!(x.type === 'text' && d.variant) && !(x.type === 'banner')) return base(el);
  const F = (k, l, ta) => ta ? `<label class="fl">${l}<textarea name="${k}" rows="3">${esc(d[k] || '')}</textarea></label>` : `<label class="fl">${l}<input name="${k}" value="${esc(d[k] || '')}" maxlength="140"></label>`;
  let b = F('eyebrow', '머리말(영문 라벨)') + `<label class="fl">제목(줄바꿈 가능)<textarea name="title" rows="2">${esc(d.title || '')}</textarea></label>`;
  if (x.type === 'banner') b += F('sub', '설명', 1) + F('cta', '주 버튼') + F('cta2', '보조 버튼');
  else { b += F('body', '설명', 1); if (d.cols) b += `<label class="fl">항목(줄마다 「제목 | 설명」)<textarea name="cols" rows="6">${esc(d.cols.map(c => c.join(' | ')).join('\n'))}</textarea></label>`; if (d.variant === 'cta') b += F('cta', '버튼 문구'); }
  modal(`${x.type === 'banner' ? '배너' : '섹션'} 편집`, b, [{ id: 'c', label: '취소' }, { id: 'ok', label: '저장', kind: 'pri', run: w => { ['eyebrow', 'title', 'sub', 'cta', 'cta2', 'body'].forEach(f => { const e = w.querySelector(`[name=${f}]`); if (e) d[f] = e.value.trim(); }); const cc = w.querySelector('[name=cols]'); if (cc) d.cols = cc.value.split('\n').map(l => l.split('|').map(v => v.trim())).filter(r => r[0]).map(r => [r[0], r[1] || '']).slice(0, 8); save(); render(); } }]); }; }
